RESULTS = []

# the engine lives in server-side Python, not the served page — a few
# checks assert against the source directly
_MILLENAI_SRC = open("millenai.py").read()

# (6b329) every personal module-level container in millenai.py is declared
# profile_cache(...) where it is made. The checks that exec a slice of the
# source get it as a builtin, so a slice doesn't need the profile
# sections; _exec_names brings the real one.
import builtins as _bi329
_bi329.profile_cache = lambda name, obj, reset=None: obj
# and threads start through ctx_thread/ctx_timer, which carry the
# starter's ctx; a slice without the profile sections gets plain threads
import threading as _th329
_bi329.ctx_thread = (lambda target, ctx=None, bind=True, **kw:
                     _th329.Thread(target=target, **kw))
_bi329.ctx_executor = lambda n: __import__("concurrent.futures").futures.ThreadPoolExecutor(n)


def _ctx_timer329(interval, fn, args=(), ctx=None):
    t = _th329.Timer(interval, fn, args)
    t.daemon = True
    return t


_bi329.ctx_timer = _ctx_timer329


# THE PROFILE SECTIONS COME ALONG (6b329). A function exec'd from the
# source may use a ctx, the profile's write primitives and the cache
# declarations, so a namespace gets millenai.py's two profile sections
# first (_exec_names does it for every one); whatever the check put in
# the namespace itself (a stub _pfile, its own StoreReadError, IS_WIN)
# wins over them.
def _prof_sect(tag):
    return _MILLENAI_SRC[_MILLENAI_SRC.index("# ==== %s: begin ====" % tag):
                         _MILLENAI_SRC.index("# ==== %s: end ====" % tag)]


_PROF_SRC = _prof_sect("profile caches") + "\n" + _prof_sect("profile")
# (6b530) the know module in the profile section reads the request's
# thread-local (know_private_now, which cloud_allowed asks), declared past
# the sections: its real declaration comes along (a missing line is loud)
_TL_DECL = next(ln for ln in _MILLENAI_SRC.splitlines()
                if ln.startswith("_tl_search = profile_cache("))


def _prof_in(ns):
    _mine = dict(ns)
    # the real modules while the sections run (a check's stand-in
    # threading has no RLock); the check's own come back after
    for _m in ("os", "json", "threading", "contextlib", "secrets", "tempfile",
               "hashlib", "time", "re", "shutil", "functools", "copy"):
        ns[_m] = __import__(_m)
    ns.setdefault("IS_WIN", False)
    ns.setdefault("TEST_HOOKS", frozenset())
    ns.setdefault("_hook_arg", lambda name: "")
    exec(_PROF_SRC, ns)
    if "_tl_search" not in _mine:
        exec(_TL_DECL, ns)
    # (6b530) no indexer thread in the test process: store_chats kicks it,
    # and a namespace's indexer (its busy test unreadable, so always busy)
    # starved this run of its GIL for hours. The live copies run the real one
    if "know_kick" not in _mine:
        ns["know_kick"] = lambda *a, **k: None
    for _m in ("os", "json", "threading", "contextlib", "secrets", "tempfile",
               "hashlib", "time", "re", "shutil"):
        ns.pop(_m, None)
    ns.update(_mine)
    for _m in ("os", "json", "threading", "contextlib", "secrets", "tempfile",
               "hashlib", "time", "re", "shutil"):
        ns.setdefault(_m, __import__(_m))


def _prof_ns(ns, d):
    """ns with the profile sections and a "This computer" ctx on folder d,
    active and bound to this thread (threads started with ns's ctx_thread
    carry it). The ctx."""
    _prof_in(ns)
    ns["app_dir"] = lambda: d
    c = ns["ProfileCtx"]("local", d)
    ns["_PROFILE"]["ctx"] = c
    ns["bind_ctx"](c)
    return c


def _pref_stubs(ns, keep_ctx=False):
    """(6b329) the settings accessors (machine_prefs, user_prefs(ctx),
    profile_local(ctx) and their updates) as stand-ins that read and write
    through the namespace's own load_prefs/store_prefs stubs, looked up at
    each call, as the code did before the split. keep_ctx: a real ctx is
    bound (_prof_ns), so bound_ctx stays. Returns ns."""
    def _load():
        return dict(ns["load_prefs"](None))

    def _upd(fn):
        d = _load()
        fn(d)
        if ns.get("store_prefs"):
            ns["store_prefs"](d, None)
        return d
    ns.update(machine_prefs=lambda strict=False: _load(),
              user_prefs=lambda ctx=None, strict=False: _load(),
              profile_local=lambda ctx=None, strict=False: _load(),
              machine_prefs_update=_upd,
              user_prefs_update=lambda ctx, fn: _upd(fn),
              profile_local_update=lambda ctx, fn: _upd(fn),
              STUDIO_NEG="neg",
              home_area=lambda: str(_load().get("home_area") or "").strip())
    if not keep_ctx:
        ns.update(bound_ctx=lambda: None, NoProfile=RuntimeError)
    return ns


def check(name, ok, detail=""):
    RESULTS.append((name, bool(ok), detail))
    print(("  PASS  " if ok else "  FAIL  ") + name + ("  — " + detail if detail and not ok else ""))


def req(path, method="GET", data=None, headers=None, cookie=None, timeout=30,
        token=None):
    h = dict(headers or {})
    # every request carries the launch key (6b310) unless a check is
    # probing the door itself with cookie=False
    if cookie is not False:
        h["Cookie"] = (cookie if cookie and K in cookie
                       else K + ("; " + cookie if cookie else ""))
    # and the API token (6b321): token=False leaves it off (the page and
    # /static/ must answer without it), a string sends that one instead;
    # an explicit X-Api-Token in headers wins
    if token is not False:
        h.setdefault("X-Api-Token", token if isinstance(token, str) else TOKEN)
    if data is not None and not isinstance(data, bytes):
        data = json.dumps(data).encode()
        h.setdefault("Content-Type", "application/json")
    r = urllib.request.Request(BASE + path, data=data, headers=h, method=method)
    try:
        with urllib.request.urlopen(r, timeout=timeout) as resp:
            return resp.status, dict(resp.headers), resp.read()
    except urllib.error.HTTPError as e:
        return e.code, dict(e.headers), e.read()


# ---- 6b441, per Patrick: an ESTIMATED prepaid Claude balance in Settings > Cloud power.
# The price math, the since-set_at filter, the unpriced path and the low/used-up levels run for
# real out of the source; the page's row renders in node; the route runs live; each rule has a
# mutant the checks must catch.
import tempfile as _tf441
_BALDIR = _tf441.mkdtemp()


def _bal_seg(src=None):
    src = src or _MILLENAI_SRC
    return src[src.index("# ==== balance: begin ===="):src.index("# ==== balance: end ====")]


def _bal_ns(src=None):
    ns = {}
    exec(_bal_seg(src), ns)
    return ns


def _bal_checks(ns):
    """Every rule, as a dict of name -> bool, against one copy of the segment."""
    out = {}
    try:
        cc, be = ns["call_cost"], ns["balance_estimate"]
        # price math: plain input, cache read, cache write and output, each at its own price
        rec = {"m": "claude-opus-5-5", "w": "claude", "t": 100, "i": 1_000_000, "c": 200_000,
               "cw": 100_000, "o": 100_000}
        out["price math, every token kind"] = abs(cc("claude", rec)[0] - 5.34) < 1e-9 \
            and abs(cc("claude", {"m": "claude-sonnet-5-5", "i": 1_000_000})[0] - 2.0) < 1e-9 \
            and abs(cc("claude", {"m": "claude-sonnet-5-5", "o": 1_000_000})[0] - 10.0) < 1e-9
        out["output tokens are counted"] = abs(cc("claude", {"m": "claude-haiku-4-5", "o": 1_000_000})[0] - 5.0) < 1e-9
        out["input and output are priced apart"] = cc("claude", {"m": "claude-opus-5", "i": 1000})[0] \
            != cc("claude", {"m": "claude-opus-5", "o": 1000})[0]
        # a dated id is the same model; "-5-6" is not "-5"
        out["dated ids price, a newer unknown does not"] = \
            ns["price_for"]("claude", "claude-opus-5-5-20260401")[1] is True \
            and ns["price_for"]("claude", "claude-opus-5-6")[1] is False \
            and ns["price_for"]("claude", "claude-sonnet-5-5")[0][0] == 2.0
        # unpriced: the most expensive price, flagged
        pr, ok = ns["price_for"]("claude", "claude-mystery-9")
        est = be("claude", {"amount_usd": 20, "set_at": 100},
                 [{"m": "claude-mystery-9", "w": "claude", "t": 200, "i": 1_000_000, "o": 0}])
        out["unpriced model: highest price, flagged"] = ok is False and pr[0] == 10.0 and pr[1] == 50.0 \
            and est["unpriced"] is True and est["spent"] == 10.0
        # since set_at
        recs = [{"m": "claude-opus-5-5", "w": "claude", "t": 99.9, "i": 1_000_000},
                {"m": "claude-opus-5-5", "w": "claude", "t": 100.0, "i": 1_000_000},
                {"m": "claude-opus-5-5", "w": "claude", "t": 150, "i": 1_000_000},
                {"m": "claude-opus-5-5", "w": "local", "t": 150, "i": 1_000_000},
                {"m": "gemini-x", "w": "gemini", "t": 150, "i": 1_000_000}]
        e = be("claude", {"amount_usd": 20, "set_at": 100.0}, recs)
        out["calls before set_at don't count, at it do, other providers never"] = \
            e["spent"] == 8.0 and e["amount"] == 12.0 and e["calls"] == 2 and e["est"] is True
        roll = [{"m": "claude-opus-5-5", "w": "claude", "t": 0, "s": 3600, "n": 10, "i": 3_600_000}]
        e2 = be("claude", {"amount_usd": 20, "set_at": 1800}, roll)
        out["a rollup that straddles set_at counts its later share"] = abs(e2["spent"] - 7.2) < 0.01 \
            and be("claude", {"amount_usd": 20, "set_at": 3600}, roll)["spent"] == 0
        # levels
        def lv(spent_amount):
            return be("claude", {"amount_usd": spent_amount, "set_at": 1}, [])["level"]
        out["levels: ok, low under $2, used up at $0 or less"] = \
            lv(2.0) == "ok" and lv(1.99) == "low" and lv(0.01) == "low" and lv(0) == "used" \
            and be("claude", {"amount_usd": 1, "set_at": 1},
                   [{"m": "claude-opus-5-5", "w": "claude", "t": 5, "o": 1_000_000}])["level"] == "used"
        out["no balance, or a bad one: no estimate"] = \
            be("claude", None, recs) is None and be("claude", {}, recs) is None \
            and be("claude", {"amount_usd": -1, "set_at": 5}, recs) is None \
            and be("claude", {"amount_usd": 5, "set_at": 0}, recs) is None
        out["free-tier and self-reporting providers get none"] = all(
            be(p, {"amount_usd": 20, "set_at": 1}, recs) is None for p in ("gemini", "groq", "kimi", "local"))
        bv = ns["balance_valid"]
        out["typed amount: finite, 0 to 100000, cents"] = bv(12.345) in (12.35, 12.34) and bv(0) == 0.0 \
            and bv(100000) == 100000.0 and bv(100000.01) is None and bv(-0.01) is None \
            and bv(float("nan")) is None and bv(float("inf")) is None and bv("5") is None \
            and bv(True) is None and bv(None) is None
    except Exception as exc:
        out["segment ran: %s" % exc] = False
    return out


