def _segs9_named(src, names):
    out = []
    for n_ in _a9.parse(src).body:
        nm_ = getattr(n_, "name", None)
        if nm_ is None and isinstance(n_, _a9.Assign):
            nm_ = next((getattr(t, "id", None) for t in n_.targets), None)
        if nm_ in names:
            out.append(_seg9(src, n_))
    return out


