# THE THREE CHIPS FOLLOW WHAT THE PERSON ASKS (6b390). Only a topic summary
# (chat titles, scrubbed and cut) is sent, in the background, to the server
# first, else a loaded model here, in Cloud Only the cloud; the summary is
# kept in the profile's suggest.json; every failure is the fixed pool.
import ast as _sg_ast
import hashlib as _sg_hash
import random as _sg_random
import threading as _sg_th

_SG_START = "# ------------------------------------------- starter chips from your chats"
_SG_END = "# ------------------------------------------------------------- voice\n"


_SG_CODE = {}


def _sg_code(src):
    """The pieces of src the block needs, parsed and compiled once per source
    (a parse of the whole file is slow, and the mutants make many namespaces)."""
    k = _sg_hash.sha1(src.encode("utf-8")).hexdigest()
    if k not in _SG_CODE:
        _SG_CODE.clear()
        out = []
        for n_ in _sg_ast.parse(src).body:
            nm = getattr(n_, "name", None)
            if nm is None and isinstance(n_, _sg_ast.Assign):
                nm = next((getattr(t, "id", None) for t in n_.targets), None)
            if nm in ("_TENDER_RX", "_looks_degenerate", "_chat_msgs", "_chat_ts",
                      "strip_think", "strip_special", "_THINK_RE", "END_TOKENS"):
                out.append(_sg_ast.get_source_segment(src, n_))
        out.append(src[src.index(_SG_START):src.index(_SG_END)])
        _SG_CODE[k] = [compile(c_, "<starter-chips>", "exec") for c_ in out]
    return _SG_CODE[k]


def _sg_ns(src, **stubs):
    """The suggestion block of src (a mutated copy too) as a namespace, with
    the real tender-topic pattern and degeneracy test, and the stubs given."""
    class StaleProfile(OSError):          # millenai's: a profile switch mid-write (6b356)
        pass
    ns = {"re": re, "random": _sg_random, "hashlib": _sg_hash, "time": time, "os": os,
          "json": json, "threading": _sg_th, "TEST_HOOKS": frozenset(),
          "_hook_arg": lambda n: "", "StaleProfile": StaleProfile}
    for c_ in _sg_code(src):
        exec(c_, ns)
    ns.update(stubs)
    return ns


def _sgc(cid, title, q, lane="ai", ts=0):
    c = {"id": cid, "lane": lane, "ts": ts,
         "messages": [{"role": "user", "content": q}, {"role": "assistant", "content": "ok"}]}
    if title is not None:
        c["title"] = title
    return c


# every chip at most 30 characters beside its emoji (6b453): the width of a third of the 780 px row
_SG_CAR = ["\U0001F527 How do I change my brake pads?", "\U0001F697 Why does my car shake so much?",
           "\U0001F6E0\uFE0F How often should I change oil?", "\U0001F6DE When should I rotate my tires?",
           "\U0001F50B Why does my battery die fast?",
           "\U0001F4A1 Why is the engine light on?"]
_SG_EAT = ["\U0001F957 What are easy healthy dinners?",
           "\U0001F34E How do I cut sugar cravings?",
           "\U0001F966 Which vegetables keep a week?"]
# the reply as a model writes it: a fragment among the good ones, and a topic with one good chip
_SG_REPLY = ("TOPIC: car repairs | COUNT: 6\n- " + "\n- ".join(_SG_CAR)
             + "\nTOPIC: healthy eating | COUNT: 2\n- " + "\n- ".join(_SG_EAT) + "\n- Meal prep ideas\n"
             + "TOPIC: sourdough | COUNT: 1\n- \U0001F35E Why won't my sourdough rise?\n")
_SG_B30 = "How do I change my brake pads?"      # 30 characters exactly
_SG_CAR2 = ["\U0001F697 Why is my car so loud lately?", "\U0001F527 Why is my car slow to start?"]


def _sg_unit(src):
    """Every behaviour of the pass that needs no running copy, by name."""
    o = {}
    labels = ["Front brake pads wear", "Easy weeknight pasta"]
    ns = _sg_ns(src)
    chip = lambda raw, lb=labels, hide=frozenset(): ns["_suggest_chip"](raw, lb, set(hide))
    o["a good chip kept as written"] = chip("\U0001F527 How do I change my brake pads?") == "\U0001F527 How do I change my brake pads?"
    o["a bullet and quotes stripped, a missing emoji supplied, the first letter raised"] = (
        chip('- "how do I bleed brakes?"') == "\U0001F4A1 How do I bleed brakes?")
    o["too short, too few words or too long refused"] = (
        chip("\U0001F527 Brakes?") is None and chip("\U0001F527 Why?!") is None and chip("\U0001F527 Why brake pads wear?") is None
        and chip("\U0001F527 How do brakes work?") is None and chip("\U0001F527 How is it?") is None
        and chip("\U0001F527 " + "How do I change my brake pads " * 4 + "?") is None and chip("\U0001F527 Brakesbrakesbrakes") is None
        and chip("\U0001F527 How is it that I can do so much on my own if it is not a big deal at all?") is None
        and chip("\U0001F527 Why do I go to bed at 2 am?") is None)       # nine words in 27 characters
    o["30 characters kept, 31 refused (6b453): a longer one is dropped, never cut"] = (
        len(_SG_B30) == 30 and chip("\U0001F527 " + _SG_B30) == "\U0001F527 " + _SG_B30
        and chip("\U0001F527 " + _SG_B30[:-1] + "s?") is None
        and chip("\U0001F3B9 How do I choose a piano for home practice?") is None
        and chip("\U0001F30D What is the official language spoken in Brazil?") is None)
    o["20 characters kept, 19 refused"] = (chip("\U0001F527 How do I fry an egg?") is not None
                                           and chip("\U0001F527 How do I fry an eg?") is None)
    o["fragments and labels with a question mark refused"] = all(chip(x) is None for x in (
        "\U0001F697 Vehicle performance?", "\U0001F30D New culture facts?", "\U0001F570\uFE0F Past era details?",
        "\u2708\uFE0F Best travel tips?", "\U0001F9D8 Does meditation actually work?",
        "\u2708\uFE0F Best travel tips for first timers?", "\U0001F697 Vehicle performance and engine upgrade options?"))
    o["no question mark, or no question word, refused"] = (
        chip("\U0001F527 How do I change my brake pads") is None and chip("\U0001F527 How do I change my brake pads.") is None
        and chip("\U0001F527 Replace the brake pads on my own car?") is None
        and chip("\U0001F527 My brake pads wear fast, why?") is None
        and chip("\U0001F527 Brake pad prices in my own town?") is None)
    o["real questions kept"] = all(chip(x) == x for x in (
        "\U0001F30D Which Portuguese city is best?",
        "\U0001F373 Can home cooking save money?",
        "\U0001F6D2 Should I buy a heat pump?",
        "\U0001F4D6 Explain how interest adds up?",
        "\U0001F4BB Tell me which laptop is best?",
        "\U0001F4C8 Isn't a slow start fixable?"))
    o["an address, a link or a long number refused"] = all(chip(x) is None for x in (
        "\U0001F527 Can I email pat@example.com?", "\U0001F527 Should I see www.example.org?",
        "\U0001F527 Can I call 5551234 for help?", "\U0001F527 Should I read https://x.io?",
        "\U0001F527 Is it example.com for brakes?"))
    o["a tender topic refused"] = all(chip(x) is None for x in (
        "\U0001F9E0 How do I handle work anxiety?", "\U0001F494 Should I leave my marriage?",
        "\U0001F48A Do medications mix with tea?", "\U0001FAC2 What helps a grieving friend?"))
    o["a word of the person's own name or place refused"] = (
        chip("\U0001F697 How do I fix a car in Denver?", hide={"denver"}) is None
        and chip("\U0001F697 How do I fix a car in Denver?") is not None)
    o["a copy of a chat they already have refused"] = (
        chip("\U0001F527 Why do front brake pads wear?") is None
        and chip("\U0001F527 How do front brake pads wear?") is None
        and chip("\U0001F527 How do I change spark plugs?") is not None)
    parse = lambda t, lb=labels, hide=frozenset(): ns["suggest_parse"](t, lb, set(hide))
    tp = parse(_SG_REPLY, labels * 4)
    o["a reply read into topics, the biggest first, six and three chips, a fragment and a one-chip topic dropped"] = (
        [t["topic"] for t in tp] == ["car repairs", "healthy eating"] and [t["n"] for t in tp] == [6, 2]
        and [t["chips"] for t in tp] == [_SG_CAR, _SG_EAT])
    tp2 = parse("TOPIC: cooking | COUNT: 1\n- \U0001F373 How do I fry an egg neatly?\n- \U0001F373 Why is my omelette rubbery?\n"
                "TOPIC: cars | COUNT: 9\n- \U0001F697 Why is my car so loud lately?\n- \U0001F697 Why is my car so loud lately?\n"
                "- \U0001F527 Why is my car slow to start?\n")
    o["biggest first whatever the order written, a repeat once, counts held to the lines sent"] = (
        [t["topic"] for t in tp2] == ["cars", "cooking"] and tp2[0]["chips"] == _SG_CAR2 and tp2[0]["n"] == 2)
    o["a near copy of another chip is dropped"] = (
        len(parse("TOPIC: cars | COUNT: 3\n- \U0001F697 Why is my car so loud lately?\n- \U0001F697 Why is my car loud lately?\n"
                  "- \U0001F527 Why is my car slow to start?\n")[0]["chips"]) == 2)
    o["no more than six chips a topic"] = len(parse("TOPIC: cars | COUNT: 3\n" + "".join(
        "- \U0001F697 Why does my %s fail?\n" % w for w in
        ("brakes", "engine", "gearbox", "clutch", "exhaust", "radiator", "starter", "alternator")))[0]["chips"]) == 6
    o["fewer than two good chips in a topic: the topic dropped; none left is nothing"] = (
        parse("TOPIC: cars | COUNT: 3\n- \U0001F697 Brakes?\n- \U0001F527 Why is my car loud at speed?\n") == []
        and parse("") == [] and parse("no topics here, sorry") == []
        and parse("TOPIC: cars | COUNT: 3\n- \U0001F697 Vehicle performance?\n- \U0001F30D New culture facts?\n") == [])
    o["a topic with no safe chip is left out, the rest kept"] = (
        [t["topic"] for t in parse("TOPIC: mail | COUNT: 4\n- \U0001F4E7 Can I mail pat@example.com?\nTOPIC: cars | COUNT: 3\n"
                                   "- \U0001F697 Why is my car so loud lately?\n- \U0001F527 Why is my car slow to start?\n")] == ["cars"])
    _ws = ("brakes", "engine", "gearbox", "clutch", "exhaust", "radiator")
    o["at most four topics"] = len(parse("".join(
        "TOPIC: t%d | COUNT: %d\n- \U0001F697 Why do my %s wear out?\n- \U0001F527 How do I check my %s?\n"
        % (i, 9 - i, _ws[i], _ws[i]) for i in range(6)), labels * 6)) == 4
    # the prompt: whole, short questions, 6 a topic, bad and good examples
    pr = ns["SUGGEST_PROMPT"]
    o["the prompt asks for 6 whole questions of 5 to 8 words and 30 characters a topic, shows bad and good, and ends at the labels"] = (
        "6 different follow-up questions" in pr and "5 to 8 words" in pr and "ends with a question mark" in pr
        and "at most 30 characters, counting spaces" in pr and "never cut off" in pr
        and "at most 4 topics" in pr and "Bad (labels and fragments)" in pr and "Vehicle performance?" in pr
        and "New culture facts?" in pr and "Bad (too long for the button)" in pr and "piano for home practice?" in pr
        and "Good (whole, short questions" in pr and "one step further" in pr
        and "never a person's name" in pr and pr.endswith("\nCHATS:\n") and pr.count("- <emoji> <question>") == 6
        and ns["SUGGEST_MAX_TOKENS"] == 1600 and ns["SUGGEST_CHIP_MIN"] == 20 and ns["SUGGEST_CHIP_MAX"] == 30
        and ns["SUGGEST_WORDS_MIN"] == 5 and ns["SUGGEST_WORDS_MAX"] == 8)
    # the prompt's own examples obey its rules
    o["the prompt's good examples pass the filter whole, its bad ones are refused"] = (
        all(chip(x) == x for x in ("\U0001F527 Are my brake rotors worn too?", "\U0001F35D Which meals keep all week?"))
        and all(chip(x) is None for x in ("\U0001F697 Vehicle performance?", "\U0001F30D New culture facts?",
                                          "\U0001F3B9 How do I choose a piano for home practice?")))
    # the picking
    pick = ns["suggest_pick"]
    cache = {"topics": tp}
    rng = _sg_random.Random(7)
    draws = [pick(cache, rng) for _ in range(60)]
    o["three chips a painting, from both topics, none twice"] = all(
        len(d) == 3 and len(set(d)) == 3 and any(c in _SG_CAR for c in d) and any(c in _SG_EAT for c in d) for d in draws)
    o["each painting draws afresh"] = len({tuple(sorted(d)) for d in draws}) >= 8
    big = {"topics": [{"topic": "a", "n": 9, "chips": ["a0 ?", "a1 ?", "a2 ?"]}, {"topic": "b", "n": 1, "chips": ["b0 ?", "b1 ?", "b2 ?"]}]}
    first_b = sum(pick(big, _sg_random.Random(i))[0].startswith("b") for i in range(400))
    o["a bigger topic is likelier but not always"] = 4 <= first_b <= 120
    pool12 = {"topics": [{"topic": "a", "n": 6, "chips": ["a%d ?" % i for i in range(6)]},
                         {"topic": "b", "n": 4, "chips": ["b%d ?" % i for i in range(4)]},
                         {"topic": "c", "n": 2, "chips": ["c%d ?" % i for i in range(2)]}]}
    pool12["pool"] = ns["suggest_pool"](pool12["topics"])
    o["the pool lists every chip with its topic"] = len(pool12["pool"]) == 12 and pool12["pool"][6] == {"c": "b0 ?", "t": 1, "n": 4}
    o["a first painting takes one chip from each of three topics"] = all(
        sorted(c[0] for c in pick(pool12, _sg_random.Random(i))) == ["a", "b", "c"] for i in range(30))

    def run10(cache_, seed, n=10):
        r_, shown_, outs = _sg_random.Random(seed), [], []
        for _ in range(n):
            ch = pick(dict(cache_, shown=list(shown_)), r_)
            outs.append(ch)
            shown_ = (shown_ + [ch])[-2:]
        return outs
    runs = [run10(pool12, sd) for sd in range(40)]
    o["10 paintings from a pool of 12: three chips each, none repeating within the last two paintings"] = all(
        all(len(o_[i]) == 3 and len(set(o_[i])) == 3 for i in range(10))
        and all(not (set(o_[i]) & set(o_[j])) for i in range(10) for j in (i - 1, i - 2) if j >= 0) for o_ in runs)
    o["...and between them they cover most of the pool"] = all(len({c for d in o_ for c in d}) >= 10 for o_ in runs)
    o["the next painting differs from the last as far as the pool allows"] = all(
        len(set(o_[i]) & set(o_[i - 1])) == 0 for o_ in runs for i in range(1, 10))
    small = {"topics": [{"topic": "a", "n": 2, "chips": ["a0 ?", "a1 ?", "a2 ?"]}, {"topic": "b", "n": 1, "chips": ["b0 ?"]}]}
    sm = pick(dict(small, shown=[["a0 ?", "a1 ?", "a2 ?"]]), _sg_random.Random(1))
    o["a pool too small to avoid: still three chips, the fresh one among them"] = len(sm) == 3 and "b0 ?" in sm
    sm2 = pick(dict(small, shown=[["a0 ?", "a1 ?"], ["a2 ?", "b0 ?"]]), _sg_random.Random(1))
    o["a small pool gives back the older painting's chips before the last one's"] = (
        len(sm2) == 3 and set(sm2) >= {"a0 ?", "a1 ?"} and len(set(sm2)) == 3)
    tie = {"topics": [dict(tp[0], n=3), dict(tp[1], n=3)]}
    td = [pick(tie, _sg_random.Random(i)) for i in range(60)]
    o["a tie for the biggest is by lot"] = (any(td[i][0] in _SG_CAR for i in range(60))
                                            and any(td[i][0] in _SG_EAT for i in range(60)))
    one = pick({"topics": [tp[0]]}, rng)
    o["one topic gives three, none gives nothing, a short pool what it has"] = (
        len(one) == 3 and all(c in _SG_CAR for c in one) and pick({}, rng) == [] and pick({"topics": []}, rng) == []
        and len(pick({"topics": [{"topic": "a", "n": 1, "chips": ["a0 ?", "a1 ?"]}]}, rng)) == 2)
    # the kept file: v2 as written, and a v1 file upgraded in the reading
    store = {}
    nsr = _sg_ns(src, _read_json=lambda f, ctx, t: store["d"], StoreReadError=OSError, NoProfile=KeyError)
    v1 = {"v": 1, "sig": "abc", "n": 9, "tried": 5, "at": 6, "checked": 7, "made": "test",
          "topics": [{"topic": "car repairs", "n": 6, "chips": ["\U0001F527 How do I change my brake pads?",
                                                                  "\U0001F697 Why does my car shake so much?",
                                                                  "\U0001F6E0 Vehicle performance?"]},
                     {"topic": "healthy eating", "n": 2, "chips": ["\U0001F957 What are easy healthy dinners?",
                                                                    "\U0001F34E How do I cut down on sugar?",
                                                                    "\U0001F966 Meal prep ideas for a week"]},
                     {"topic": "travel", "n": 1, "chips": ["\U0001F30D New culture facts?", "\u2708\uFE0F Best travel tips?",
                                                            "\U0001F4CD Why is my car so loud at low speed?"]}]}
    store["d"] = v1
    up = nsr["suggest_read"](None)
    o["a v1 file is read as v2: fragments dropped, a topic with fewer than two good chips dropped, a pool built, a new pass due"] = (
        up["v"] == 2 and up["upgraded"] is True and up["sig"] == "" and up["shown"] == []
        and [t["topic"] for t in up["topics"]] == ["car repairs", "healthy eating"]
        and up["topics"][0]["chips"] == v1["topics"][0]["chips"][:2]
        and len(up["topics"][1]["chips"]) == 2 and "\U0001F966 Meal prep ideas for a week" not in str(up)
        and [e["c"] for e in up["pool"]] == up["topics"][0]["chips"] + up["topics"][1]["chips"]
        and nsr["suggest_due"](dict(up, tried=time.time() - 3600, at=time.time(), checked=time.time())) is True
        and nsr["suggest_due"](dict(up, tried=time.time() - 60)) is False
        and len(nsr["suggest_pick"](up, rng)) == 3 and all(c in str(up["pool"]) for c in nsr["suggest_pick"](up, rng)))
    store["d"] = {"v": 2, "topics": tp, "pool": [{"c": "x ?", "t": 0, "n": 1}], "shown": [["x ?"]]}
    o["a v2 file is read as it is, anything else as nothing"] = (
        nsr["suggest_read"](None) == store["d"] and not (store.update(d=[1]) or nsr["suggest_read"](None))
        and not (store.update(d={"v": 3}) or nsr["suggest_read"](None)))
    # a v2 file from before 6b453: chips up to 90 characters, which overran their chips
    v2old = {"v": 2, "sig": "abc", "n": 9, "at": 6, "checked": 7, "tried": 5, "made": "test", "shown": [["x ?"]],
             "topics": [{"topic": "pianos", "n": 6, "chips": ["\U0001F3B9 How do I choose a piano for home practice?",
                                                             "\U0001F3B9 Which piano suits a flat?", "\U0001F3B9 Is a digital piano enough?"]},
                        {"topic": "history", "n": 2, "chips": ["\U0001F3E0 How did households manage without electricity?",
                                                              "\U0001F30D What is the official language spoken in Brazil?"]}]}
    v2old["pool"] = ns["suggest_pool"](v2old["topics"])
    store["d"] = v2old
    up2 = nsr["suggest_read"](None)
    o["a v2 file with long chips is read like a v1: the long ones gone, the short kept, a pool rebuilt, a new pass due at once"] = (
        up2["v"] == 2 and up2["upgraded"] is True and up2["sig"] == "" and up2["shown"] == []
        and [t["topic"] for t in up2["topics"]] == ["pianos"] and up2["topics"][0]["chips"] == v2old["topics"][0]["chips"][1:]
        and [e["c"] for e in up2["pool"]] == v2old["topics"][0]["chips"][1:] and "home practice" not in str(up2)
        and all(len(e["c"].split(" ", 1)[1]) <= 30 for e in up2["pool"])
        and nsr["suggest_due"](dict(up2, tried=time.time() - 3600, at=time.time(), checked=time.time())) is True)
    # the labels
    chats = [_sgc("a%d" % i, "Brakes %d topic" % i, "q", ts=1000 - i) for i in range(40)]
    lb, n = ns["suggest_labels"](chats)
    o["the newest 30 labels, every chat counted"] = len(lb) == 30 and n == 40 and lb[0] == "Brakes 0 topic"
    lb, n = ns["suggest_labels"]([
        _sgc("1", "Fix nginx", "q", lane="code", ts=9), _sgc("2", "Funnel thing", "q", lane="funnel", ts=8),
        _sgc("3", "Therapy for anxiety", "q", ts=7), _sgc("4", None, "my sourdough is flat, any ideas", ts=6),
        _sgc("5", "Old chat (copy)", "how do I pickle onions", ts=5),
        _sgc("6", "Mail pat@example.com about https://x.example/y or 5551234567", "q", ts=4),
        _sgc("7", "A" * 90, "q", ts=3), _sgc("8", "Brakes", "q", ts=2),
        {"id": "9", "lane": "ai", "ts": 1, "title": "No messages", "messages": []}])
    o["only chat-lane chats, no tender label, a missing or copied title from the first question"] = (
        lb == ["my sourdough is flat, any ideas", "how do I pickle onions", "Mail about or", "A" * 60, "Brakes"] and n == 6)
    o["an address, a link and a long number scrubbed from a label, a long one cut at 60"] = (
        "Mail about or" in lb and "A" * 60 in lb and all(len(x) <= 60 for x in lb))
    # the model asked
    calls = []
    srv, loc, cloud, up = [None], [None], [[]], [True]

    def _stubs(tier="Fast"):
        return dict(
            profile_local=lambda ctx: {"tier": tier},
            gate_ladder=lambda lad, req=None, only=False: lad if only else [],
            cloud_only_tier=lambda t: t == "Cloud Only", cloud_tier_pid=lambda t: "",   # (6b440)
            fast_cloud_ladder=lambda utility=False: cloud[0],
            cloud_text=lambda c, m, **k: (calls.append("cloud") or "<think>x</think>CLOUD " + c["id"]),
            server_side_text=lambda m, ctx=None, role="fast", max_tokens=0: (calls.append("server") or srv[0]),
            _suggest_local_label=lambda: loc[0],
            server_mode_candidates=lambda ctx: ([{"sid": "s"}] if up[0] else []),
            _srv_seen={"s": {"at": time.time()}},
            run_model=lambda lb_, m, emit: (calls.append("local") or emit("LOCAL " + lb_)),
            strip_think=lambda t: t.replace("<think>x</think>", ""), strip_special=lambda t: t)

    def ask(nsx):
        calls.clear()
        r = nsx["suggest_ask"](None, "p")
        return r, list(calls)
    cloud[0] = [{"id": "g"}]
    srv[0], loc[0] = "SERVER", "Phi"
    up[0] = True
    ns2 = _sg_ns(src, **_stubs())
    o["the server first"] = ask(ns2) == (("SERVER", "your server"), ["server"])
    up[0] = False
    o["a server that is not answering is not asked, and never woken"] = ask(ns2) == (("LOCAL Phi", "this computer"), ["local"])
    up[0] = True
    ns2["_srv_seen"]["s"]["at"] = time.time() - 99999
    o["a server last heard from long ago is not asked either"] = ask(ns2) == (("LOCAL Phi", "this computer"), ["local"])
    ns2["_srv_seen"]["s"]["at"] = time.time()
    srv[0] = None
    o["then a loaded model of this computer"] = ask(ns2) == (("LOCAL Phi", "this computer"), ["server", "local"])
    loc[0] = None
    o["no model free: nothing, and the cloud never asked"] = ask(ns2) == ((None, ""), ["server"])
    srv[0], loc[0] = "SERVER", "Phi"
    ns3 = _sg_ns(src, **_stubs("Cloud Only"))
    o["Cloud Only: the cloud and nothing else"] = ask(ns3) == (("CLOUD g", "the cloud"), ["cloud"])
    cloud[0] = []
    o["Cloud Only with no cloud: nothing, never the server or a local model"] = ask(ns3) == ((None, ""), [])
    cloud[0] = [{"id": "g"}]
    ns4 = _sg_ns(src, **dict(_stubs("Thinking"), profile_local=lambda ctx: (_ for _ in ()).throw(KeyError("x"))))
    o["a profile whose mode can't be read is not Cloud Only"] = ask(ns4) == (("SERVER", "your server"), ["server"])
    o["the loaded-model pick wants a capable one already up"] = (
        _sg_ns(src, MODEL_ROUTES={"A": ("mlx", 1), "B": ("mlx", 2), "C": ("ollama", "c:1")},
               MODEL_MEM_BYTES={"A": 1e9, "B": 9e9, "C": 3e9}, _engine_up=lambda p: p == 2,
               _ollama_loaded=lambda: ["c:1"])["_suggest_local_label"]() == "C"
        and _sg_ns(src, MODEL_ROUTES={"A": ("mlx", 1)}, MODEL_MEM_BYTES={"A": 1e9}, _engine_up=lambda p: True,
                   _ollama_loaded=lambda: [])["_suggest_local_label"]() is None
        and _sg_ns(src, MODEL_ROUTES={"B": ("mlx", 2)}, MODEL_MEM_BYTES={"B": 9e9}, _engine_up=lambda p: False,
                   _ollama_loaded=lambda: [])["_suggest_local_label"]() is None)

    # busy
    def busy(**k):
        st = dict(turns_live_count=lambda ctx: 0, _bench={"running": False}, _bench_busy={"n": 0, "srv": 0},
                  _modup={"state": "idle"}, _setup_lock=_sg_th.Lock(), _setup_jobs={})
        st.update(k)
        return _sg_ns(src, **st)["suggest_busy"](None)
    o["nothing running is not busy"] = busy() is False
    o["an answer being written is busy"] = busy(turns_live_count=lambda ctx: 1) is True
    o["a benchmark is busy"] = (busy(_bench={"running": True}) is True and busy(_bench_busy={"n": 1, "srv": 0}) is True
                                and busy(_bench_busy={"n": 0, "srv": 1}) is True)
    o["a model download or an update is busy"] = (
        busy(_setup_jobs={"M": {"status": "downloading"}}) is True and busy(_setup_jobs={"M": {"status": "queued"}}) is True
        and busy(_modup={"state": "running"}) is True and busy(_setup_jobs={"M": {"status": "done"}}) is False)
    o["a question it can't answer is busy"] = busy(turns_live_count=lambda ctx: 1 / 0) is True
    # when a pass is due
    due = ns["suggest_due"]
    now = time.time()
    h = 3600
    ns["_suggest_state"].clear()
    full = {"topics": [{"topic": "x", "n": 1, "chips": ["a b"]}], "at": now - 1 * h, "checked": now - 1 * h, "tried": now - 1 * h}
    o["a fresh summary is left alone"] = due(full) is False
    o["a summary older than six hours is looked at again"] = due(dict(full, at=now - 7 * h, checked=now - 7 * h, tried=now - 7 * h)) is True
    o["a look made lately counts as fresh"] = due(dict(full, at=now - 7 * h, checked=now - 1 * h, tried=now - 1 * h)) is False
    o["no summary yet is due, a quarter hour apart"] = (
        due({}) is True and due({"tried": now - 5 * 60}) is False and due({"tried": now - 20 * 60}) is True)
    o["a failed pass is not repeated for fifteen minutes, old summary or not"] = (
        due(dict(full, at=now - 7 * h, checked=now - 7 * h, tried=now - 60)) is False)
    o["a refresh asked for is due whatever the age"] = due(full, True) is True
    ns["_suggest_state"]["running"] = True
    o["never two at once"] = due({}) is False and due(full, True) is False
    ns["_suggest_state"].clear()
    ns["_suggest_state"]["hold"] = now + 60
    o["held back while something was busy"] = due({}) is False and due(full, True) is True
    # the switch
    o["the switch is on unless saved off"] = (
        _sg_ns(src, user_prefs=lambda ctx: {})["suggest_on"](None) is True
        and _sg_ns(src, user_prefs=lambda ctx: {"suggest_own": True})["suggest_on"](None) is True
        and _sg_ns(src, user_prefs=lambda ctx: {"suggest_own": False})["suggest_on"](None) is False
        and _sg_ns(src, user_prefs=lambda ctx: 1 / 0)["suggest_on"](None) is False)

    # a pass, end to end, on stand-ins for the store and the model
    def run_pass(chats, old=None, on=(True,), busy_=False, answer=(_SG_REPLY, "test"), force=False, user=None, boom=False):
        written, asks, seq = [], [], iter(on)

        def load(ctx):
            if boom:
                raise OSError("x")
            return chats
        nsx = _sg_ns(src, suggest_on=lambda ctx: next(seq, on[-1]), _chats_lock=_sg_th.Lock(), load_chats=load,
                     suggest_read=lambda ctx: dict(old or {}), _write_json=lambda n_, d, ctx, **k: written.append(d),
                     suggest_busy=lambda ctx: busy_, user_prefs=lambda ctx: dict(user or {}),
                     suggest_ask=lambda ctx, p: (asks.append(p) or answer))
        nsx["_suggest_state"].clear()
        nsx["_suggest_state"]["running"] = True
        nsx["suggest_pass"](None, force)
        return written, asks, nsx
    five = [_sgc("p%d" % i, t, "q", ts=100 - i) for i, t in enumerate(
        ["Replacing front brake pads", "Car shaking", "Oil change interval", "Easy weeknight pasta", "Spark plugs"])]
    w, a, nsx = run_pass(five)
    o["a pass keeps the topics, who wrote them and when, and asks once with the labels only"] = (
        len(w) == 1 and len(a) == 1 and a[0] == nsx["SUGGEST_PROMPT"] + "\n".join(
            ["Replacing front brake pads", "Car shaking", "Oil change interval", "Easy weeknight pasta", "Spark plugs"])
        and [t["topic"] for t in w[0]["topics"]] == ["car repairs", "healthy eating"] and w[0]["made"] == "test"
        and w[0]["v"] == 2 and w[0]["n"] == 5 and abs(w[0]["at"] - time.time()) < 30 and len(w[0]["sig"]) == 40
        and [e["c"] for e in w[0]["pool"]] == _SG_CAR + _SG_EAT and w[0]["upgraded"] is False)
    o["a pass always ends: the running flag is cleared"] = nsx["_suggest_state"].get("running") is False
    w, a, nsx = run_pass(five[:2])
    o["fewer than three chats: kept as none, no model asked"] = (
        a == [] and len(w) == 1 and w[0]["topics"] == [] and w[0]["n"] == 2 and w[0]["at"] == 0)
    sig = _sg_hash.sha1("\n".join(["Replacing front brake pads", "Car shaking", "Oil change interval",
                                   "Easy weeknight pasta", "Spark plugs"]).encode()).hexdigest()
    oldc = {"v": 2, "sig": sig, "topics": [{"topic": "x", "n": 1, "chips": ["zzz yyy"]}], "pool": [{"c": "zzz yyy", "t": 0, "n": 1}],
            "at": 5, "checked": 5, "made": "z", "shown": [["zzz yyy"]]}
    w, a, nsx = run_pass(five, old=oldc)
    o["nothing new: only looked at, not asked"] = (a == [] and len(w) == 1 and w[0]["checked"] > time.time() - 30
                                                   and w[0]["topics"] == oldc["topics"] and w[0]["at"] == 5)
    w, a, nsx = run_pass(five, old=oldc, force=True)
    o["a refresh asks though nothing is new"] = len(a) == 1 and w[0]["made"] == "test"
    o["a pass replaces the pool wholesale: no old chip lingers; what was shown is kept"] = (
        [e["c"] for e in w[0]["pool"]] == _SG_CAR + _SG_EAT and "zzz yyy" not in str(w[0]["topics"]) + str(w[0]["pool"]) and w[0]["shown"] == [["zzz yyy"]]
        and w[0]["sig"] == sig)
    w, a, nsx = run_pass(five, old=dict(oldc, upgraded=True))
    o["an upgraded v1 summary is asked again though the titles are as they were"] = (
        len(a) == 1 and w[0]["made"] == "test" and w[0]["upgraded"] is False and len(w[0]["pool"]) == 9)
    w, a, nsx = run_pass(five, busy_=True)
    o["busy: nothing asked, nothing written, held back"] = (
        a == [] and w == [] and nsx["_suggest_state"].get("hold", 0) > time.time() + 30)
    w, a, nsx = run_pass(five, on=(True, False))
    o["switched off while it ran: nothing written"] = len(a) == 1 and w == []
    w, a, nsx = run_pass(five, old=oldc, answer=(None, ""), force=True)
    o["no answer: the old topics stay, the try is noted"] = (
        len(a) == 1 and len(w) == 1 and w[0]["topics"] == oldc["topics"] and w[0]["at"] == 5 and w[0]["tried"] > time.time() - 30)
    w, a, nsx = run_pass(five, old=dict(oldc, sig="oldsig", pool=oldc["pool"]), answer=(None, ""))
    o["a pass that fails keeps the old sig and pool, so the next look asks again"] = (
        len(w) == 1 and w[0]["sig"] == "oldsig" and w[0]["pool"] == oldc["pool"])
    w, a, nsx = run_pass(five, answer=("I cannot help with that.", "test"))
    o["an answer that is no list: the try is noted, no topics"] = w[0]["topics"] == [] and w[0]["tried"] > time.time() - 30
    w, a, nsx = run_pass(five, user={"user_name": "Dana Whitfield"},
                         answer=("TOPIC: cars | COUNT: 3\n- \U0001F697 Why is Dana's car so loud?\n"
                                 "- \U0001F527 Why is my car slow to start?\n"
                                 "- \U0001F527 Why is my car so loud lately?\n", "test"))
    o["a word of the person's own name keeps a chip out"] = (
        len(w) == 1 and w[0]["topics"] and not any("Dana" in c for c in w[0]["topics"][0]["chips"])
        and len(w[0]["topics"][0]["chips"]) == 2)
    w, a, nsx = run_pass(five, boom=True)
    o["a failure is swallowed and the pass still ends"] = w == [] and nsx["_suggest_state"].get("running") is False

    # starting one
    def start(on_, due_):
        started = []

        class _T:
            def start(self_):
                started.append(1)
        nsx = _sg_ns(src, suggest_on=lambda c: on_, suggest_read=lambda c: {},
                     suggest_due=lambda cache, force=False: due_, ctx_thread=lambda target=None, args=(), daemon=False: _T())
        nsx["_suggest_state"].clear()
        return nsx["suggest_start"](None), len(started), nsx["_suggest_state"].get("running")
    o["a pass starts when it is on and due, once, marked running"] = start(True, True) == (True, 1, True)
    o["not when it is off or not due"] = start(False, True) == (False, 0, None) and start(True, False) == (False, 0, None)

    # what the route answers
    def view(on_=True, busy_=False, cache=None, refresh=False):
        forgot, forced = [], []
        kept = {"d": cache or {}}
        nsx = _sg_ns(src, suggest_on=lambda c: on_, suggest_busy=lambda c: busy_, suggest_read=lambda c: dict(kept["d"]),
                     suggest_forget=lambda c: forgot.append(1), _write_json=lambda n_, d, ctx, **k: kept.update(d=dict(d)),
                     suggest_start=lambda c, force=False: (forced.append(force) or True))
        nsx["_suggest_state"].clear()
        nsx["_kept"] = kept
        return nsx["suggest_view"](None, refresh), forgot, forced
    good = {"v": 2, "topics": tp, "at": 5, "made": "test", "n": 9}
    r, f, g = view(cache=good)
    o["the route gives three chips at once, and starts a pass if one is due"] = (
        len(r["chips"]) == 3 and r["on"] is True and r["n"] == 9 and r["topics"] == ["car repairs", "healthy eating"]
        and r["started"] is True and g == [False])
    r, f, g = view(on_=False, cache=good)
    o["switched off: the pool, the summary erased, no pass"] = (
        r == {"on": False, "chips": [], "refreshing": False} and f == [1] and g == [])
    r, f, g = view(on_=False)
    o["switched off with nothing kept: nothing to erase"] = f == []
    r, f, g = view(busy_=True, cache=good, refresh=True)
    o["busy: the kept chips, no pass, and it says why"] = r["busy"] is True and r["started"] is False and g == [] and len(r["chips"]) == 3
    r, f, g = view(cache=good, refresh=True)
    o["Refresh forces a pass"] = g == [True] and r["started"] is True
    # every look a different set, remembered in the profile's own file, two paintings deep
    kept = {"d": dict(good, pool=ns["suggest_pool"](tp))}
    nsv = _sg_ns(src, suggest_on=lambda c: True, suggest_busy=lambda c: False, suggest_read=lambda c: dict(kept["d"]),
                 _write_json=lambda n_, d, ctx, **k: kept.update(d=dict(d)), suggest_start=lambda c, force=False: False)
    nsv["_suggest_state"].clear()
    seq = [nsv["suggest_view"](None)["chips"] for _ in range(10)]
    o["each look of the route gives a new set: three chips, none repeating within two looks, most of the pool seen"] = (
        all(len(x) == 3 for x in seq) and all(not (set(seq[i]) & set(seq[j])) for i in range(10) for j in (i - 1, i - 2) if j >= 0)
        and len({c for x in seq for c in x}) >= 8)
    o["what was shown is written to the profile's file, the last two looks only, the rest of the summary kept"] = (
        kept["d"]["shown"] == seq[-2:] and kept["d"]["topics"] == tp and kept["d"]["v"] == 2)
    kept = {"d": {"v": 2, "topics": [], "pool": []}}
    nsv = _sg_ns(src, suggest_on=lambda c: True, suggest_busy=lambda c: False, suggest_read=lambda c: dict(kept["d"]),
                 _write_json=lambda n_, d, ctx, **k: kept.update(d=dict(d)), suggest_start=lambda c, force=False: False)
    nsv["_suggest_state"].clear()
    o["nothing to show writes nothing"] = nsv["suggest_view"](None)["chips"] == [] and kept["d"] == {"v": 2, "topics": [], "pool": []}
    return o


