          + "{name:'old:7b',label:'Desktop \\u00b7 old:7b',placement:'unknown'}]},"
          + "{id:'e5f6a7b8',name:'Studio',host:'s.example.com',paired:false,status:{at:1,"
          + "reachable:false,err:'Studio didn\\u2019t answer.',kind:'offline'},models:[]},"
