def _p4c_rules(src):
    """The rules review (6b339): "<name> Only" makes no picture or video and asks no model to word one, runs no agent;
    Cloud Only never contacts the server; a seat's title is the server's or none; the agent switch off in the page."""
    ch = src[src.index('        if self.path != "/api/chat":'):]
    ns, ctx, d = _sv_ns(src)
    # image_followup exec'd with a stand-in for the model that words a refinement: refine=False never asks it
    asked = []
    fns = {"re": re, "_IMG_NEWTOPIC": re.compile(r"^\\b$"), "image_intent": lambda t: None, "video_intent": lambda t: None,
           "export_intent": lambda *a: None, "_IMG_CHANGE": re.compile(r"(?P<rest>.*)"), "_subject_words": lambda s_: set(),
           "_IMG_LEADIN": re.compile(r"^$"), "_refine_with_model": lambda prev, said, server=True: asked.append(said) or "a bluer cat"}
    exec(_p2_fn(src, "image_followup"), fns)
    r1 = fns["image_followup"]("make it bluer", "a red cat", refine=False)
    n1 = len(asked)
    r2 = fns["image_followup"]("make it bluer", "a red cat")
    t = ns["server_seat_title"]
    down = lambda l: l == "B · y"
    S = {"A · x": "L", "B · y": "L"}
    got = {
        "no refine for Only": n1 == 0 and r1 != "a bluer cat" and len(asked) == 1 and r2 == "a bluer cat"
        and "    said = _refine_with_model(prev_subject, t, server) if refine else \"\"" in src
        and "refine=not srv_only_tier(tier),\n                                          server=not cloud_only)" in ch,
        # "<name> Only" makes no picture or video (said, one line, nothing made, before the benchmark hold)
        "no pictures": "        if _srv_only and (img_subject or vid_subject):\n" in ch
        and "            emit(AppText(\"%s Only can’t make pictures or video. Nothing was made.\"" in ch
        and ch.index("        if _srv_only and (img_subject or vid_subject):\n")
        < ch.index("        if (img_subject or vid_subject or export_req or edit_req) and not self._bench_held:"),
        # and no agent: refused, the agent not resolved, nothing run
        "no agents": "        if agent_name and srv_only_tier(tier):\n" in ch
        and "            _so_fail = (\"%s Only can’t run the %s agent. Nothing ran.\" % (_so_c0.split(SERVER_SEP, 1)[0]\n" in ch
        and "            agent_name = \"\"\n        ag_system, ag_research, ag_remote = \"\", False, False" in ch,
        # a seat's chat is titled by the server that answered, or by none; never by this Mac
        "seat title": t(["A · x"], {"A · x": "L"}, "server", True, False, down) == "A · x"
        and t(["A · x"], {"A · x": "L"}, "fallback", True, False, down) == ""
        and t(["A · x"], {"A · x": "L"}, "failed", False, False, down) == ""
        and t(["A · x"], {"A · x": "L"}, "", True, False, down) is None
        and t(["A · x"], {"A · x": "L"}, "server", True, True, down) is None
        and t(["A · x", "L1"], {"A · x": "L"}, "", True, False, down) == "A · x"
        and t(["B · y", "A · x"], S, "", True, False, down) == "A · x"
        and t(["B · y"] * 2, S, "", True, False, down) == ""
        and t(["A · x", "L1"], {"A · x": "L"}, "", False, False, down) == ""
        and t(["L1"], {}, "", True, False, down) is None,
    }
    # setAgent turns an Only pick off (node)
    i0 = src.index("function setAgent(name,guess){")
    fn = src[i0:src.index("\n}\n", i0) + 3]
    js = ("let tier='srv:a1b2c3d4',agent='';const po=[];const calls=[];function isSrvMode(t){return t.indexOf('srv:')===0;}"
          "function prefSet(o){po.push(JSON.stringify(o));}function paintAgents(){}function paintModels(){calls.push('paint');}"
          + fn + "const out={};setAgent('Coding');out.a=[tier,agent,po.slice()];po.length=0;"
          "tier='Pro';setAgent('Coding');out.b=[tier,po.slice()];po.length=0;"
          "tier='srv:a1b2c3d4';setAgent('');out.c=[tier,po.slice()];po.length=0;setAgent('Workspace',true);out.d=[tier,po.slice()];"
          "process.stdout.write(JSON.stringify(out));")
    try:
        o = _so_node("sa39.js", js)
    except Exception as e_:
        return False, "node: %r" % e_
    got["agent turns Only off"] = (o["a"][0] == "Fast" and o["a"][1] == "Coding"
                                   and json.loads(o["a"][2][0]) == {"agent": "Coding", "codeagent": "Coding", "tier": "Fast"}
                                   and o["b"][0] == "Pro" and "tier" not in json.loads(o["b"][1][0])
                                   and o["c"][0] == "srv:a1b2c3d4" and "tier" not in json.loads(o["c"][1][0])
                                   and o["d"][0] == "Fast")
    return all(got.values()), [got, o]


def _p5c_nodes(src):
    """The page's pieces of the final review, run in node: a quick click on a server's row clears the hover timer; the
    switch refreshes the chip, the bubbles and the greyed rows; Fast with the cloud first doesn't claim the server; the
    bubble says when the cap bound; the switch's label and help say what the Code lane sends."""
    i0 = src.index("function esc(s){")
    esc = src[i0:src.index(";}\n", i0) + 3]
    fly = src[src.index("function flyClick("):src.index("// ONE ROW OF A MODE (6b442)")]
    row = src[src.index("// a click on a server's row (6b339, final review)"):src.index("function openEngMenu(){")]
    pref = src[src.index('$("#srv-list").addEventListener("change",async ev=>{'):src.index('$("#srv-list").addEventListener("keydown"')]
    pop = src[src.index("function showTierPop(el,name){"):src.index("// THE COMPOSITOR SECTION (6b442)")]
    shown = src[src.index("function isSrvMode(t){"):src.index("function tierLabel(){")]
    js = (esc + 'const SRV_SEP=" \\u00b7 ";let srvList=[],tierInfo={},tier="Fast",model="x",srvLoaded=true;' + shown + fly
          + "const log=[];let engSubTimer=0,engSubId='',engSubByHover=false;const engSub={hidden:true};"
          + "function closeEngSub(){log.push('close');engSub.hidden=true;engSubId='';}"
          + "function openEngSub(id,k,h){log.push('open:'+id+':'+h);engSubId=id;engSub.hidden=false;engSubByHover=!!h;}"
          + row
          + "const h={};const $=s=>({addEventListener:(t,f)=>{h[t]=f;}});const calls=[];"
          + "function srvPost(){calls.push('post');return Promise.resolve({server:{id:'x',prefer:false}});}"
          + "function srvPut(){calls.push('put');}function paintServers(){calls.push('paint');}function srvMsg(){calls.push('msg');}"
          + "function srvModesRefresh(){calls.push('modes');}function paintTierAvail(){calls.push('avail');}"
          + "function paintEngMenuServers(){calls.push('menu');}"
          + pref
          + "const tierPop={innerHTML:'',hidden:true,offsetWidth:100,offsetHeight:60,style:{},classList:{add(){},remove(){},contains(){return true;}}};const innerWidth=1000,innerHeight=800;"
          # (6b442: the pop-out is drawn from what /api/tiers last said, beside the menus, with its compositor below)
          + "let detEl=null,detT='',cloudSt=null;const document={querySelectorAll:()=>[]};const engMenu={contains:()=>false};engSub.contains=()=>false;"
          + "function compHtml(){return '';}function placeTierPop(){tierPop.hidden=false;}"
          + "const T={Pro:{models:['A \\u00b7 a','A \\u00b7 b','Gemma'],srvcap:{seated:4,of:6},skipped:[]},"
          + "Thinking:{models:['A \\u00b7 a'],skipped:[]}};"
          + "async function api(p){return {json:async()=>p==='/api/tiers'?T:{configured:false,turbo:false}};}"
          + pop
          + "(async()=>{const out={};"
          # a quick click: the hover timer a mouseenter set is cleared, so it never re-opens the flyout as a hover one
          + "let fired=0;engSubTimer=setTimeout(()=>{fired=1;log.push('timer');},60);srvRowClick('a1');"
          + "await new Promise(r=>setTimeout(r,160));out.quick=[fired,log.slice(),engSubByHover];"
          # a click while a hover-opened flyout is up keeps it, pinned; another click closes it
          + "log.length=0;engSubId='a1';engSub.hidden=false;engSubByHover=true;srvRowClick('a1');out.pin=[log.slice(),engSubByHover];"
          + "srvRowClick('a1');out.close=log.slice();"
          # the switch: the modes' seats, the tiers and the open menu follow now
          + "await h.change({target:{closest:s=>s.indexOf('prefer')>=0?{checked:false,closest:()=>({dataset:{id:'x'}})}:null}});"
          + "out.pref=calls.slice();"
          # Fast with the cloud first doesn't name the server; Thinking still does
          + "tierInfo={Fast:{models:['Desk \\u00b7 gpt-oss:20b'],fastcloud:'Groq'},Thinking:{models:['A \\u00b7 x'],fastcloud:'Groq'}};"
          + "out.chip=[tierShown('Fast'),tierShown('Thinking')];tierInfo={Fast:{models:['Desk \\u00b7 gpt-oss:20b']}};out.chip2=tierShown('Fast');"
          # the bubble: Pro says it seats four of six; Thinking says nothing of it
          + "const el={getBoundingClientRect:()=>({right:10,left:5,top:5}),classList:{add(){}}};"
          + "tierInfo=T;await showTierPop(el,'Pro');out.pro=tierPop.innerHTML;await showTierPop(el,'Thinking');out.th=tierPop.innerHTML;"
          + "process.stdout.write(JSON.stringify(out));})();")
    try:
        o = _so_node("p5c.js", js)
    except Exception as e_:
        return False, "node: %r" % e_
    got = {
        "quick click": o["quick"][0] == 0 and o["quick"][1] == ["open:a1:false"] and o["quick"][2] is False,
        "pin, close": o["pin"] == [[], False] and o["close"] == ["close"],
        "switch": o["pref"] == ["post", "put", "paint", "modes", "avail", "menu"],
        "chip": o["chip"] == ["Fast", "Thinking \u00b7 A"] and o["chip2"] == "Fast \u00b7 Desk gpt-oss:20b",
        "bubble": "4 of 6 server models fit the time a blend has" in o["pro"] and "server models fit" not in o["th"],
        # the switch's words: the Code lane's agents read a folder, and what they read goes to the model that answers
        "label": "<span>Use for Fast, Thinking, Pro and Code</span></label>'" in src
        and "      +'<div class=\"srv-hint\">Code agents may send a folder you choose to this server.</div>':\"\")"
            "" in src,
        "tiers say the cap": "                if _cap:\n                    out[name][\"srvcap\"] = {\"seated\": _cap[0], \"of\": _cap[1]}" in src,
        "wired": "        ev.stopPropagation();hideTierPop();\n        srvRowClick(el.dataset.sv);" in src
        and "      clearTimeout(engSubTimer);if(engSubByHover&&!det.aiming())closeEngSub();});" in src,
    }
    return all(got.values()), [got, o]


def _p6c_chooser(src):
    """6b344: the model of the server that writes a mode's merge. The seats' chooser and filters (a coder, an embedding, a
    guard, a picture reader or a reasoning distill never; gpu placement, fitting a card whose size is reported, the
    switch on); the strongest by size; a model the council just drafted with (the server holds two) when it is within
    70% of the strongest's size; none when no server qualifies."""
    models = [_m("gpt-oss:20b", size=13 * GIB_), _m("mistral-small:24b", size=14 * GIB_), _m("gemma3:12b", size=8 * GIB_),
              _m("qwen3-coder:30b", size=12 * GIB_), _m("nomic-embed-text:335m", size=GIB_), _m("llama-guard3:8b", size=5 * GIB_),
              _m("llava:13b", size=8 * GIB_), _m("deepseek-r1:14b", size=9 * GIB_), _m("hog:70b", "gpu+ram", 40 * GIB_)]
    ns, ctx, ents = _p2_ns(src, [("Desk", "https://desk.example.com", models, {})])
    pick = lambda d=(): (ns["server_compositor"](ctx, d) or {}).get("name")
    L = lambda n_: "Desk · " + n_
    ok = ns["srv_role_ok"]
    got = {
        "strongest": pick() == "mistral-small:24b",
        "families": all(not ok(n_, "compose") for n_ in ("qwen3-coder:30b", "nomic-embed-text:335m", "llama-guard3:8b",
                                                         "llava:13b", "deepseek-r1:14b"))
        and all(ok(n_, "compose") for n_ in ("gpt-oss:20b", "mistral-small:24b", "gemma3:12b")),
        # the council's last two drafters are what the server still holds: one within 70% of the strongest takes the pen
        "resident": pick([L("gpt-oss:20b")]) == "gpt-oss:20b"
        and pick([L("gemma3:12b"), L("gpt-oss:20b")]) == "gpt-oss:20b"
        and pick([L("gpt-oss:20b"), L("gemma3:12b")]) == "gpt-oss:20b",
        # ...never a much smaller one, and only the last two count
        "not a small one": pick([L("gemma3:12b")]) == "mistral-small:24b"
        and pick([L("gpt-oss:20b"), L("gemma3:12b"), L("gemma3:12b")]) == "mistral-small:24b",
        # a model of this computer's among the drafts is not the server's
        "local draft": pick(["Gemma 4 26B"]) == "mistral-small:24b",
    }
    _so_seen(ns, ents["Desk"], [dict(m_, loaded=True) if m_["name"] == "gpt-oss:20b" else m_ for m_ in models],
             gpu=dict(_P2_GPU))
    got["the server says it holds one"] = pick() == "gpt-oss:20b"
    _so_seen(ns, ents["Desk"], models, gpu=dict(_P2_GPU))
    # nothing to write it: no server, the switch off, a server that doesn't answer, only gpu+ram models, no card figure
    n0, c0, e0 = _p2_ns(src, [])
    got["no server"] = n0["server_compositor"](c0, []) is None
    ns["server_set_prefer"](ctx, ents["Desk"]["id"], False)
    got["switch off"] = pick() is None
    ns["server_set_prefer"](ctx, ents["Desk"]["id"], True)
    _so_seen(ns, ents["Desk"], models, reachable=False, err="down", gpu=dict(_P2_GPU))
    got["down"] = pick() is None
    _so_seen(ns, ents["Desk"], [_m("gpt-oss:20b", "gpu+ram", 13 * GIB_), _m("deepseek-r1:14b", size=9 * GIB_)], gpu=dict(_P2_GPU))
    got["no suitable model"] = pick() is None
    _so_seen(ns, ents["Desk"], models, gpu=None)
    got["no card figure"] = pick() is None
    return all(got.values()), got


def _p6c_merge(src):
    """6b344: in a mode (srv_merge) the server writes the merge: the same first-word deadline and marked-down rules as a
    draft; before its first word a failure falls to this computer's pen (or the best draft), said in the status line,
    with the frames that name where; after one there is ONE answer, cut there and said. A cloud pen still comes first; an
    Advanced council, a named pen and a machine with no server are as they were."""
    def rm(label, msgs, emit, thinking=False):
        emit("answer from " + label + " " * 3)
    box, asked = {}, []
    CHOSEN = {"label": "Desk · b", "name": "b", "server": "Desk"}

    def comp(ctx, drafted=()):
        asked.append(list(drafted))
        return CHOSEN
    info = {"Gemma 4 26B": {"ollama": "gemma4:26b", "size": "26B"}}
    kw = dict(merge_pref_label=lambda: "Gemma 4 26B", MODEL_ROUTES={"Gemma 4 26B": ("ollama", "gemma4:26b")},
              MODEL_INFO=info, MERGE_RANK=["Gemma 4 26B"])

    def go(srv_merge, labels=("Desk · a", "Desk · b", "Llama"), over_run=None, **over):
        ns, calls = _p2_council(src, over_run or rm, **over)
        box["ns"] = ns
        out, fr, st = [], [], []
        ns["run_council"](list(labels), [{"role": "user", "content": "q"}],
                          lambda c: (fr if isinstance(c, _RcCtl) else out).append(c), st.append,
                          srv_merge=srv_merge, srv_first_s=60.0, **over.pop("run_kw", {}))
        return ns, calls, out, fr, st

    def sg_factory(mode):
        seen = []

        def sg(label, msgs, emit, status, fb, note):
            seen.append(label)
            if label.startswith("Desk"):
                if mode == "late":
                    emit("partial ")
                raise box["ns"]["ServerError"]("Desk didn’t answer.")
            emit("LOCAL MERGE")
            return True
        return sg, seen
    got = {}
    # on the server, inside the mode's deadline, the card and the badge naming it; what drafted on the server was said
    ns, calls, out, fr, st = go(True, server_compositor=comp, **kw)
    got["on the server"] = (calls == [("merge", "Desk · b", 60.0)] and "MERGED" in out and asked == [["Desk · a", "Desk · b"]])
    got["the card"] = any('"STEP:' in f or "STEP:" in f for f in fr) and any(
        "STEP:" in f and "Writing the answer" in f and "Desk \\u00b7 b" in f and '"s": "run"' in f for f in fr) and any(
        "STEP:" in f and "Answer written" in f for f in fr)
    got["the badge"] = any("RUN:" in f and '"w": "mix"' in f and "Desk \\u00b7 a" in f and "Desk \\u00b7 b" in f
                           and "Llama" in f for f in fr)
    # no server: byte for byte what it was (the chooser said none)
    a = go(True, server_compositor=lambda c, d=(): None, **kw)
    b = go(False, **kw)
    # (the drafts run in threads, so what is compared is the merge stage: its calls, its text, its status and its frames)
    tail = lambda r: (r[1], r[2], [x for x in r[4] if not x.startswith("asking")],
                      [f for f in r[3] if "STEP:" in f or "mix" in f or "RESET" in f])
    got["no server: as before"] = (tail(a) == tail(b) and a[1][0][1] == "Gemma 4 26B" and tail(a)[3] == [])
    # an Advanced council (no srv_merge) never asks the chooser
    n_asked = len(asked)
    c = go(False, server_compositor=comp, **kw)
    got["advanced untouched"] = len(asked) == n_asked and c[1][0][1] == "Gemma 4 26B"
    # a pen named in Advanced stays
    d = go(True, server_compositor=comp, run_kw={"comp": "Gemma 4 26B"}, **kw)
    got["named pen"] = [x[:2] for x in d[1]] == [("merge", "Gemma 4 26B")]
    # a cloud pen comes first: the server isn't asked to write it
    cl = go(True, server_compositor=comp, cloud_allowed=lambda: True, compositor_ladder=lambda: [{"model": "cloud-pen"}],
            cloud_stream_conf=lambda c_, m_, e_: (e_("CLOUD " * 40), True)[1], **kw)
    got["cloud first"] = cl[1] == [] and any("CLOUD" in x for x in cl[2])
    # Pro: the server holds what it used LAST, the peer reviews after the drafts, so the chooser is told that order
    def long_rm(label, msgs, emit, thinking=False):
        emit("x " * 130)
    n_ask = len(asked)
    ns_p, calls_p = _p2_council(src, long_rm, server_compositor=comp, **kw)
    ns_p["run_council"](["Desk · a", "Desk · b", "Desk · c"], [{"role": "user", "content": "q"}], lambda c: None,
                        [].append, peer=True, srv_merge=True, srv_first_s=60.0)
    got["resident after peer review"] = (len(asked) == n_ask + 1 and asked[-1] == ["Desk · a", "Desk · b", "Desk · c"] * 2)
    # a draft that failed is not a model the server holds
    def bad_rm(label, msgs, emit, thinking=False):
        if label.startswith("Lab · bad"):
            raise box["ns"]["ServerError"]("Lab didn’t answer.")
        emit("answer from " + label + " " * 3)
    n_ask = len(asked)
    ns_b, calls_b = _p2_council(src, bad_rm, server_compositor=comp, **kw)
    box["ns"] = ns_b
    ns_b["run_council"](["Desk · a", "Lab · bad", "Lab2 · b"], [{"role": "user", "content": "q"}], lambda c: None,
                        [].append, srv_merge=True, srv_first_s=60.0)
    got["a failed draft is not held"] = len(asked) == n_ask + 1 and sorted(asked[-1]) == ["Desk · a", "Lab2 · b"]
    # before its first word: this computer's pen, said, the server marked down, the frames name where
    sg, seen = sg_factory("early")
    f1 = go(True, server_compositor=comp, _stream_guarded=sg, **kw)
    got["refused: this computer's pen"] = (
        seen == ["Desk · b", "Gemma 4 26B"] and "LOCAL MERGE" in f1[2]
        and "Desk didn’t write the final. Gemma 4 26B writes it here." in f1[4]
        and f1[0]["_downs"] == [("Desk", "Desk didn’t answer.")]
        and len([f for f in f1[3] if "RUN:" in f and '"w": "mix"' in f]) == 2
        and any("RUN:" in f and '"w": "mix"' in f and "Gemma 4 26B" in f for f in f1[3])
        and not any("RESET" in f for f in f1[3]))
    # no pen of this computer's: the best draft ships, said
    sg, seen = sg_factory("early")
    f2 = go(True, server_compositor=comp, _stream_guarded=sg, model_cached=lambda l, p=None: l != "Gemma 4 26B", **kw)
    got["refused: the best draft"] = (seen == ["Desk · b"] and "LOCAL MERGE" not in f2[2]
                                      and any(x.startswith("answer from") for x in f2[2])
                                      and "Desk didn’t write the final. The best single draft is shown." in f2[4])
    # a Stop, a closed window or a profile switch while the server writes it (the review of 6b344): not the server's
    # failure (no mark down), and no compositor of this computer's for a client that is gone
    for exc_name in ("StaleProfile", "BrokenPipeError"):
        seen_x = []

        def sx(label, msgs, emit, status, fb, note, _n=exc_name):
            seen_x.append(label)
            raise (box["ns"]["StaleProfile"]("switched") if _n == "StaleProfile" else BrokenPipeError())
        try:
            fx = go(True, server_compositor=comp, _stream_guarded=sx, **kw)
            got["a %s mid-merge" % exc_name] = False
        except (OSError, BrokenPipeError):
            got["a %s mid-merge" % exc_name] = seen_x == ["Desk · b"] and box["ns"]["_downs"] == []
    # after its first word: one answer, cut there and said; no pen of this computer's, no second answer
    sg, seen = sg_factory("late")
    f3 = go(True, server_compositor=comp, _stream_guarded=sg, **kw)
    got["cut after a word"] = (seen == ["Desk · b"] and f3[2][0] == "partial " and f3[2][-1].startswith("\n\n⚠️")
                               and "LOCAL MERGE" not in f3[2] and f3[0]["_downs"] == [("Desk", "Desk didn’t answer.")]
                               and not any("RESET" in f for f in f3[3]))
    return all(got.values()), got


def _p6c_page(src):
    """6b344 on the page: the badge names where an answer was written (a RUN frame with the models that ran, "mix"), and the
    handler asks for a server merge only for a mode."""
    ch = src[src.index('        if self.path != "/api/chat":'):]
    i0 = src.index("function whereBadge(lm,who){")
    fn = src[i0:src.index("// what a click on a server's row does to its flyout")]
    js = ('const SRV_SEP=" \\u00b7 ";' + fn + "const out={};"
          "out.all=whereBadge('Ollama1 \\u00b7 a, Ollama1 \\u00b7 b','');"
          "out.mixed=whereBadge('Ollama1 \\u00b7 a, Ollama1 \\u00b7 b, Gemma 4 26B','');"
          "out.back=whereBadge('Ollama1 \\u00b7 a, Ollama1 \\u00b7 b, Gemma 4 26B','Ollama1');"
          "process.stdout.write(JSON.stringify(out));")
    try:
        o = _so_node("p6c.js", js)
    except Exception as e_:
        return False, "node: %r" % e_
    got = {
        "badge": o["all"] == "Ollama1" and o["mixed"] == "this Mac + Ollama1",
        "frame read": '                  else if(d.w==="local"||d.w==="mix"){srvWho="";if(d.m)lastModels=String(d.m);}' in src,
        "modes only": "                            srv_merge=(tier in TIERS and not cloud_only))" in ch
        and "    if srv_merge and comp not in MODEL_ROUTES and not cloud_only and _pen_kind != \"local\":\n" in src,
        "cloud first": src.index("    elif cloud_allowed():\n        if _walk_ladder():\n            return _done()\n    run_mark(compositor=merger)\n"
                                 "    report[\"writer\"] = merger\n    if _merge_srv is not None:")
        > 0,
    }
    return all(got.values()), [got, o]


def _p7c_vision(src):
    """6b357: which model of the person's server reads a picture sent in a mode. The seats' rules (a paired server of
    this profile with the switch on, answering, "gpu" models that fit a reported card); what the server says it can do
    (Ollama's /api/show "capabilities", through the gateway, remembered); never a coder, embedding or guard model; the
    strongest first; at most six asked; none when nothing qualifies or the server doesn't answer."""
    models = [_m("qwen2.5vl:7b", size=6 * GIB_), _m("gemma3:12b", size=8 * GIB_), _m("gpt-oss:20b", size=13 * GIB_),
              _m("llava:34b", "gpu+ram", 20 * GIB_), _m("qwen3-coder:30b", size=12 * GIB_),
              _m("nomic-embed-text:335m", size=GIB_), _m("llama-guard3-vision:11b", size=7 * GIB_)]
    vis = {"qwen2.5vl:7b", "gemma3:12b", "llava:34b", "qwen3-coder:30b", "llama-guard3-vision:11b"}
    ns, ctx, ents = _p2_ns(src, [("Desk", "https://desk.example.com", models, {})])
    asked, mode = [], {"st": 200}

    def sj(e, method, path, obj=None, *a, **k):
        asked.append((path, (obj or {}).get("model")))
        if mode["st"] != 200:
            return mode["st"], {"error": "down", "code": "busy"}
        return 200, {"capabilities": ["completion", "vision"] if obj["model"] in vis else ["completion"]}
    ns["_srv_json"] = sj
    pick = lambda c=ctx: (ns["server_vision_pick"](c) or {}).get("name")
    got = {"strongest that reads pictures": pick() == "gemma3:12b"
           and asked == [("/api/show", "gpt-oss:20b"), ("/api/show", "gemma3:12b")]}
    pick()
    got["remembered"] = len(asked) == 2
    # nothing that reads pictures: none, and no more than six asked
    many = [_m("plain%d:8b" % i, size=5 * GIB_) for i in range(9)]
    _so_seen(ns, ents["Desk"], many, gpu=dict(_P2_GPU))
    asked.clear()
    got["none, six asked"] = pick() is None and len(asked) == 6
    # the server doesn't answer the question: this computer reads it
    _so_seen(ns, ents["Desk"], models, gpu=dict(_P2_GPU))
    mode["st"] = 503
    got["server error"] = pick() is None
    mode["st"] = 200
    _so_seen(ns, ents["Desk"], models, gpu=dict(_P2_GPU))
    ns["server_set_prefer"](ctx, ents["Desk"]["id"], False)
    got["switch off"] = pick() is None
    ns["server_set_prefer"](ctx, ents["Desk"]["id"], True)
    n0, c0, e0 = _p2_ns(src, [])
    got["no server"] = n0["server_vision_pick"](c0) is None
    _so_seen(ns, ents["Desk"], models, gpu=None)
    got["no card figure"] = pick() is None
    return all(got.values()), got


def _p7c_side(src):
    """6b357: a side pass on the person's server first: its quick model (7-15B, the faster measured), inside a 30 s
    first-word deadline; a failure marks the server down and says None, so the caller runs what it ran before; a Stop
    or a profile switch is not a failure; no server, None."""
    models = [_m("gpt-oss:20b", size=13 * GIB_), _m("qwen3:14b", size=9 * GIB_), _m("gemma3:12b", size=8 * GIB_)]
    ns, ctx, ents = _p2_ns(src, [("Desk", "https://desk.example.com", models, {})])
    calls, mode = [], {"x": None}

    def ss(label, msgs, emit, cap=0):
        calls.append((label, getattr(ns["_srv_first"], "s", None), msgs[-1]["content"]))
        if mode["x"]:
            raise mode["x"]
        emit("  the text  ")
    ns["server_stream"] = ss
    ns.setdefault("strip_think", lambda x: x)        # (the chat section's, not the servers')
    ask = [{"role": "user", "content": "TITLE IT"}]
    got = {"on the server": ns["server_side_text"](ask, ctx) == "  the text  "
           and calls == [("Desk · qwen3:14b", 30.0, "TITLE IT")]}
    mode["x"] = ns["StaleProfile"]("switched")
    try:
        ns["server_side_text"](ask, ctx)
        got["a switch is raised"] = False
    except ns["StaleProfile"]:
        got["a switch is raised"] = not ns["server_label_down"](ctx, "Desk · qwen3:14b")
    mode["x"] = BrokenPipeError()
    try:
        ns["server_side_text"](ask, ctx)
        got["a stop is raised"] = False
    except BrokenPipeError:
        got["a stop is raised"] = not ns["server_label_down"](ctx, "Desk · qwen3:14b")
    mode["x"] = ns["ServerError"]("offline", "Desk didn’t answer.")
    got["a failure: None, marked down"] = (ns["server_side_text"](ask, ctx) is None
                                           and ns["server_label_down"](ctx, "Desk · qwen3:14b"))
    calls.clear()
    got["down: not asked"] = ns["server_side_text"](ask, ctx) is None and calls == []
    # a first word that took too long (a cold load of the title model) leaves the server for this pass: it is NOT down
    ns["server_check"] = lambda e, limit=None: None
    _so_seen(ns, ents["Desk"], models, gpu=dict(_P2_GPU))
    mode["x"] = ns["ServerSlow"]("offline", "Desk sent nothing for 30 seconds, so the answer stopped there.")
    got["too slow: None, not down"] = (ns["server_side_text"](ask, ctx) is None
                                       and not ns["server_label_down"](ctx, "Desk \u00b7 qwen3:14b")
                                       and ns["ServerSlow"].slow is True and ns["ServerError"].slow is False)
    n0, c0, e0 = _p2_ns(src, [])
    got["no server"] = n0["server_side_text"](ask, c0) is None
    return all(got.values()), got


def _p7c_passes(src):
    """6b357: each side pass that ran on this computer asks the person's server first and runs its own model only when
    the server says None: the chat's title (a seat's export title never locally), an image prompt's rewrite, the
    Remote agent's planner (its coder; a failed turn marks the server down and the next resolve is local), Research
    (the server plans and writes; before its first word this computer's writer, after one the answer cut there)."""
    got = {}
    ran = []
    srv = {"text": "Lighthouse history"}
    base = {"TITLE_PROMPT": "NAME IT: ", "_clean_title": lambda x: " ".join(str(x).split())[:40],
            "server_side_text": lambda msgs, ctx=None, role="fast": srv["text"],
            "_ticket_conf": lambda c: None, "cloud_role_model": lambda *a: "", "cloud_text": lambda *a, **k: "",
            "ollama_pulled_tags": lambda: set(), "model_cached": lambda l, p=None: True, "model_fits_memory": lambda l: True,
            "slow_giant": lambda l: False, "MODEL_ROUTES": {"Llama 3.2 3B": ("mlx", 1)}, "MODEL_MEM_BYTES": {"Llama 3.2 3B": 3e9},
            "_engine_up": lambda p: True, "strip_think": lambda x: x, "strip_special": lambda x: x,
            "_looks_degenerate": lambda x: False, "re": re,
            "run_model": lambda l, m, cb, **k: (ran.append(l), cb("Local title"))[1],
            "server_stream": lambda *a, **k: None}
    ns = dict(base)
    exec(_p2_fn(src, "make_title"), ns)
    t1 = ns["make_title"]("tell me about lighthouses")
    got["title: the server's"] = t1 == "Lighthouse history" and ran == []
    srv["text"] = None
    t2 = ns["make_title"]("tell me about lighthouses")
    got["title: no server, this computer's"] = t2 == "Local title" and ran == ["Llama 3.2 3B"]
    ran.clear()
    got["a seat's export: never this computer"] = ns["make_title"]("x", local=False) == "" and ran == []
    srv["text"] = ""
    got["the server answered nothing: no local try"] = ns["make_title"]("x") == "" and ran == []
    # an image prompt's rewrite
    ns = dict(base)
    srv["text"] = "a red bicycle by the sea, at dusk"
    ns.update(_REFINE_PROMPT="%s / %s")
    exec(_p2_fn(src, "_refine_with_model"), ns)
    ran.clear()
    r1 = ns["_refine_with_model"]("a red bicycle", "at dusk")
    srv["text"] = None
    ns["run_model"] = lambda l, m, cb, **k: (ran.append(l), cb("a blue bicycle by the sea"))[1]
    r2 = ns["_refine_with_model"]("a red bicycle", "make it blue")
    got["rewrite: the server's, else a resident one"] = (r1 == "a red bicycle by the sea, at dusk" and r2 == "a blue bicycle by the sea"
                                                         and ran == ["Llama 3.2 3B"])
    # the Remote agent: the server's coder after the cloud, before this computer; a failed turn marks it down
    downs = []
    pick = {"m": {"label": "Desk · qwen3-coder:30b", "server": "Desk"}}
    rns = {"cloud_allowed": lambda: False, "work_ladder": lambda r: [], "bound_ctx": lambda: None, "NoProfile": KeyError,
           "server_side_pick": lambda ctx, role="fast", effort="fast": pick["m"] if role == "code" and effort == "normal" else None,
           "ollama_pulled_tags": lambda: set(), "MODEL_ROUTES": {"GPT-OSS 20B": 1}, "model_cached": lambda l, p=None: True,
           "model_fits_memory": lambda l: True, "strip_think": lambda x: x, "cloud_text": lambda *a, **k: "",
           # (6b405) the code ladder is the one constant the sets read too
           "CODE_LADDER": ("Qwen 3.8 27B", "Qwen 3.6 35B MoE", "GPT-OSS 20B", "Gemma 4 26B",
                           "Qwen 3.5 9B", "Gemma 4 12B", "Llama 3.2 3B"),
           "server_first_deadline": _RcDeadline, "server_mark_down": lambda c, n, w: downs.append(n),
           "SERVER_SEP": " · ", "StaleProfile": type("StaleProfile", (OSError,), {})}
    seen = []

    def rm(l, convo, cb, **k):
        seen.append((l, getattr(_RC_DL, "s", "unset")))
        if l.startswith("Desk") and pick.get("fail"):
            raise RuntimeError("down")
        cb('{"run": "uptime"}')
    rns["run_model"] = rm
    exec(_p2_fn(src, "remote_driver"), rns)
    exec(_p2_fn(src, "_agent_turn"), rns)
    d1 = rns["remote_driver"]()
    o1 = rns["_agent_turn"](d1, [{"role": "user", "content": "q"}])
    pick["fail"] = True
    o2 = rns["_agent_turn"](d1, [{"role": "user", "content": "q"}])
    pick["m"] = None
    d2 = rns["remote_driver"]()
    got["remote: the server's coder, then this computer"] = (
        d1 == ("server", "Desk · qwen3-coder:30b") and o1 == '{"run": "uptime"}' and seen[0] == ("Desk · qwen3-coder:30b", 60.0)
        and o2 == "" and downs == ["Desk"] and d2 == ("local", "GPT-OSS 20B"))
    # Research: the server plans and writes; a refusal before the first word is this computer's writer, said
    out, st, seen2 = [], [], []

    def sg(label, msgs, emit, status, fb, note):
        seen2.append((label, getattr(_RC_DL, "s", "unset")))
        if label.startswith("Desk") and pick.get("rfail"):
            if pick["rfail"] == "late":
                emit("partial ")
            raise RuntimeError("down")
        emit("BRIEF by " + label)
        return True
    res = {"HAS_SEARCH": True, "MERGE_RANK": ["Gemma 4 26B"], "model_cached": lambda l, p=None: True,
           "model_fits_memory": lambda l: True, "bound_ctx": lambda: None, "NoProfile": KeyError,
           "server_compositor": lambda ctx, d=(): {"label": "Desk · gpt-oss:20b"},
           "server_first_deadline": _RcDeadline, "SRV_SIDE_FIRST_S": 30.0,
           "_plan_queries": lambda w, q, s: (seen2.append(("plan", w, getattr(_RC_DL, "s", "unset"))), [])[1],
           "search_results": lambda q: [{"url": "https://e.test/1", "body": "b" * 50, "title": "T"}],
           "_page_text": lambda u: "", "ctx_thread": lambda target, args=(), **k: _t34.Thread(target=target, args=args),
           "RESEARCH_WRITE": "W", "_stream_guarded": sg, "server_label": lambda l: " · " in str(l),
           "SERVER_SEP": " · ", "Ctl": _RcCtl, "server_mark_down": lambda c, n, w: downs.append("R:" + n),
           "StaleProfile": type("StaleProfile", (OSError,), {})}
    exec(_p2_fn(src, "run_research"), res)
    msgs = [{"role": "system", "content": "s"}, {"role": "user", "content": "what is new"}]
    res["run_research"](["Gemma 4 26B"], msgs, out.append, st.append)
    got["research: the server plans and writes"] = (
        ("plan", "Desk · gpt-oss:20b", 30.0) in seen2 and ("Desk · gpt-oss:20b", 60.0) in seen2
        and any("BRIEF by Desk" in x for x in out))
    out.clear(), st.clear(), seen2.clear()
    pick["rfail"] = "early"
    res["run_research"](["Gemma 4 26B"], msgs, out.append, st.append)
    got["research: a refusal, this computer writes it"] = (
        any("BRIEF by Gemma 4 26B" in x for x in out) and "R:Desk" in downs
        and any("didn’t answer. Gemma 4 26B writes it here." in x for x in st))
    out.clear(), st.clear(), seen2.clear()
    pick["rfail"] = "late"
    res["run_research"](["Gemma 4 26B"], msgs, out.append, st.append)
    got["research: cut after a word"] = (out[0] == "partial " and out[1].startswith("\n\n⚠️")
                                         and not any("Gemma" in x for x in out))
    return all(got.values()), got


def _p7c_pins(src):
    """6b357, where the handler meets it (the live checks run these on the real gateway; pinned here so a mutation of
    each line is caught in process): a picture in a mode only, Cloud Only and a pick untouched; the server reads it after
    the cloud and before this computer; no download while the server can read it; the memory pass, the place pins and
    the rescue ask the server first for an answer of this computer's."""
    ch = src[src.index('        if self.path != "/api/chat":'):]
    got = {
        "a mode only": "            _mode_pic = tier in TIERS and not cloud_only\n" in ch
        and ch.index("            _mode_pic = tier in TIERS and not cloud_only\n") < ch.index('            tier = ""\n            b64s = ['),
        "the seat": "                council = [_vis_srv[\"label\"]]\n                model_name = _vis_srv[\"label\"]\n"
                    "                _seat_fb = {_vis_srv[\"label\"]: _vfb}\n" in ch,
        "cloud, then the server": "            if cloud_only or (not _vis_local and _vis_srv is None):\n" in ch
        and "            return cloud_only or (not _vis_local and _vis_srv is None)" in ch,
        "no download": "                and not _srv_lbl and _vis_srv is None):\n            try:\n                # a Claude or Gemini key would read it with the switch on" in ch and "                vision_offer(emit, _vkey)" in ch,   # 6b628: asked, never started
        "memory": "            out = (None if server_label(label) or cloud_only\n                   else server_side_text(ask, base))\n" in src,
        "pins": "                                _ps = (None if server_label(small)\n"
                "                                       else server_side_text(_pin_ask, user_base))\n" in ch,
        "a video's own overrides": "        if vid_subject and _skey != \"video\":\n            _skey = \"video\"\n"
                                   "            _ovr, _pclean, _onotes = gen_overrides(prompt, \"video\", _loose, {})\n" in ch,
        "no wake from a side pass": not any(
            w in _p2_fn(src, f) for f in ("server_side_pick", "server_side_text", "server_vision_pick", "server_compositor")
            for w in ("server_wake", "server_refresh_modes", "server_check(")),
        "rescue": "                _rs = (server_side_pick(user_base, \"fast\", \"normal\")\n                       if not images else None)\n" in ch
        and "                if not sent[0]:\n                    try:\n                        pulled = ollama_pulled_tags() or set()" in ch,
    }
    return all(got.values()), got


def _p8c_cloud_only(src):
    """6b357 (review): Cloud Only never sends text to a server. The title (and an export's title), an image prompt's rewrite
    and the memory pass skip the server when asked to (the handler passes cloud_only), and /api/title knows a Cloud Only
    chat from the ticket its last turn left; the same calls without it still ask the server."""
    ran, srv = [], []
    base = {"TITLE_PROMPT": "NAME IT: ", "_clean_title": lambda x: " ".join(str(x).split())[:40],
            "server_side_text": lambda msgs, ctx=None, role="fast": (srv.append(msgs[-1]["content"][:8]), "Server title")[1],
            "_ticket_conf": lambda c: None, "cloud_role_model": lambda *a: "", "cloud_text": lambda *a, **k: "",
            "ollama_pulled_tags": lambda: set(), "model_cached": lambda l, p=None: True, "model_fits_memory": lambda l: True,
            "slow_giant": lambda l: False, "MODEL_ROUTES": {"Llama 3.2 3B": ("mlx", 1)}, "MODEL_MEM_BYTES": {"Llama 3.2 3B": 3e9},
            "_engine_up": lambda p: True, "strip_think": lambda x: x, "strip_special": lambda x: x,
            "_looks_degenerate": lambda x: False, "re": re,
            "run_model": lambda l, m, cb, **k: (ran.append(l), cb("Local title"))[1], "server_stream": lambda *a, **k: None}
    ns = dict(base)
    exec(_p2_fn(src, "make_title"), ns)
    got = {"title: asked the server": ns["make_title"]("hello there") == "Server title" and len(srv) == 1,
           "title: Cloud Only skips it": (ns["make_title"]("hello there", ask_server=False) == "Local title"
                                          and len(srv) == 1 and ran == ["Llama 3.2 3B"])}
    ns = dict(base)
    ns["_REFINE_PROMPT"] = "%s / %s"
    exec(_p2_fn(src, "_refine_with_model"), ns)
    srv.clear(), ran.clear()
    ns["run_model"] = lambda l, m, cb, **k: (ran.append(l), cb("a blue bicycle by the sea"))[1]
    ns["server_side_text"] = lambda msgs, ctx=None, role="fast": (srv.append(1), "a red bicycle by the sea at dusk")[1]
    r_srv = ns["_refine_with_model"]("a red bicycle", "at dusk")
    r_co = ns["_refine_with_model"]("a red bicycle", "make it blue", False)
    got["rewrite: the server's, and Cloud Only's never"] = (r_srv == "a red bicycle by the sea at dusk" and len(srv) == 1
                                                           and r_co == "a blue bicycle by the sea" and ran == ["Llama 3.2 3B"])
    return all(got.values()), got


def _p8c_slow(src):
    """6b357 (review): a time limit is "left for this computer", never "down". A picture or a video that outlasted its cap
    (ServerSlow), like a first word that took too long, says it took too long and falls back WITHOUT marking the server
    down; a refusal or a connection failure still does."""
    downs, said, steps = [], [], []
    ns = {"server_refresh_modes": lambda ctx, **k: None, "server_take_wake_notes": lambda: [], "_srv_plain": lambda n: n,
          "server_gen_sleepers": lambda ctx, kind: [],              # (6b482) nobody asleep
          "server_take_quiet_notes": lambda: [],                   # (6b600) nobody kept asleep by quiet hours
          "server_gen_pick": lambda ctx, kind: {"name": "Desk", "id": "x"}, "srv_gen_opts": lambda kind, use: {"width": 8, "height": 8},
          "ServerGenStopped": type("ServerGenStopped", (Exception,), {}),
          "StaleProfile": type("StaleProfile", (OSError,), {}), "_client_gone": lambda sock: False,
          "server_mark_down": lambda ctx, n, w: downs.append((n, w)), "_SRV_GEN_WHY": {"offline": "didn’t answer"}}
    exec(src[src.index("class ServerError(RuntimeError):"):src.index("def _srv_conn(")], ns)
    exec(_p2_fn(src, "server_make"), ns)
    box = {}

    def gen(e, kind, subject, opts, status, gone):
        raise box["x"]
    ns["server_generate"] = gen
    got = {}
    for name, exc in (("too long", ns["ServerSlow"]("offline", "Desk took more than 5 minutes to make the picture.")),
                      ("a refusal", ns["ServerError"]("offline", "Desk didn’t answer."))):
        downs.clear(), said.clear()
        box["x"] = exc
        r = ns["server_make"](None, "image", "a cat", {}, [], None, lambda *a: None, lambda *a: steps.append(a), said.append)
        got[name] = (r is False and (downs == []) == (name == "too long")
                     and any(("took too long" in x) == (name == "too long") for x in said[-1:]))
    # where the limits are raised: a first word or a quiet stretch past the limit, and a job past its cap
    got["limits are slow"] = ('                    raise ServerSlow("offline", "%s went quiet for %s. The answer stopped there." % (' in src
                              and '                raise ServerSlow("offline", "%s took over %d minutes on the %s. It was stopped." % (' in src)
    return all(got.values()), got


def _p8c_pins(src):
    """6b357 (review), where Cloud Only meets the three sites that reached a server: the image follow-up's rewrite, an
    export's title and /api/title (its ticket, set by the Cloud Only turn); every other server-first call site is
    guarded by its own cloud_only line or never runs in a Cloud Only chat (listed in NOTES)."""
    ch = src[src.index('        if self.path != "/api/chat":'):]
    ti = src[src.index('        if self.path == "/api/title":'):]
    ti = ti[:ti.index('        if self.path == "/api/open-logs":')]
    got = {
        "follow-up": "                                          refine=not srv_only_tier(tier),\n"
                     "                                          server=not cloud_only)" in ch
        and "    said = _refine_with_model(prev_subject, t, server) if refine else \"\"" in src,
        "export title": "                     make_title(src[:600], local=not _seat_fb,\n"
                        "                                ask_server=not cloud_only))" in ch,
        "/api/title": "            _co = bool(_tcid and time.time() - _cloud_only_chats.get(" in ti
        and "make_title(txt, conf=_conf, ask_server=not _co)" in ti,
        "the ticket": "        if cloud_only and _title_cid:\n            _cloud_only_chats[(self.ctx.name, _title_cid)] = time.time()" in ch
        and "        _cloud_only_chats.pop((self.ctx.name, _title_cid), None)  # 6b357" in ch,
        "memory": "            out = (None if server_label(label) or cloud_only\n                   else server_side_text(ask, base))" in src,
    }
    return all(got.values()), got


