    ("stray", 'if(s.mode!=="hold")return "";', "if(false)return \"\";"),
    ("blur", 'idle();return ev.rec?"stop":"";', 'idle();return "";'),
    ("blurbutton", 'idle();return ev.rec?"stop":"";', 'const m=s.mode;idle();return m&&ev.rec?"stop":"";'),
