def _r519_all(src):
    out = {}
    for fn in (_r519_helpers, _r519_loop, _r519_pins):
        try:
            for k, v in fn(src).items():
                out[fn.__name__[6:] + ": " + k] = bool(v)
        except Exception as e_:
            out[fn.__name__[6:] + ": raised %r" % (e_,)] = False
    return out


