    u_ = S_.get("update") or {}
    k_["update"] = ((u_.get("at1") or {}).get("line") == "No internet connection. Connect and try again." and (u_.get("at5") or {}).get("line") == "No internet connection. Connect and try again."
                    and (u_.get("at5") or {}).get("key") == "Check now")
    return k_
